const app=document.querySelector('#app');let me=null,data=null,platform=null,connection=null,view='dashboard',org='',message='',extended=null,preview=null,expenseData=null,expenseDestinations=null,pendingExpenseId=new URLSearchParams(location.search).get('expense')||'';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(label,name,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,choices,value='')=>`<label>${esc(label)}<select name="${name}">${choices.map(c=>{let [v,l]=Array.isArray(c)?c:[c,c];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
const card=(t,b)=>`<section class="card"><h2>${esc(t)}</h2>${b}</section>`;
const table=(headers,rows)=>rows.length?`<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="empty">No records.</p>';
const stat=items=>`<div class="cards">${items.map(([l,n,s])=>`<section class="card stat"><span>${esc(l)}</span><strong>${esc(n)}</strong><small>${esc(s)}</small></section>`).join('')}</div>`;
const button=(label,action,extra='')=>`<button data-action="${action}" ${extra}>${esc(label)}</button>`;
async function api(path,body){document.body.setAttribute('aria-busy','true');let r;try{r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)})}finally{document.body.removeAttribute('aria-busy')}let d=await r.json();if(!r.ok){if(r.status===401&&me){me=null;history.replaceState(null,'','/login');authPage()}throw Error(d.error||'Request failed')}return d}
async function refresh(){if(me.role==='owner'){platform=await api('/api/platform/overview');platform.settings=await api('/api/platform/settings');for(let o of platform.organisations){o.connection=(await api('/api/'+o.id+'/state')).connection}}if(org){data=await api('/api/'+org+'/workspace');connection=await api('/api/'+org+'/state');extended=me.role==='owner'&&!data.workspace.ownerRecordAccess?{entities:[],rules:[],sources:[],capabilities:{},templates:[]}:await api('/api/'+org+'/platform');expenseData=data.workspace.modules.expenses?await api('/api/'+org+'/expenses'):null}render()}
function authPage(){let path=location.pathname,register=path==='/register',accept=path==='/accept-invite',owner=path==='/owner-login';app.innerHTML=`<div class="topnotice">Demonstration configuration — no client records shipped. Individual accounts and server permissions are enforced.</div><div class="auth-layout"><section class="auth-brand"><img class="logo" src="logo.png" alt="OperaOS"><span class="auth-kicker">Your operations, connected</span><h2>One workspace.<br>A clearer workday.</h2><p>Manage people, requests and records with the tools your organisation needs.</p><div class="auth-feature">Organisations · Workflows · Reporting</div></section><section class="card auth"><span class="auth-kicker">${owner?'Platform owner':register?'Get started':'Your workspace'}</span><h1>${register?'Create your workspace':accept?'Accept your invitation':owner?'Welcome back, owner':'Welcome back'}</h1><p>${register?'Your account becomes administrator of your new, separate workspace.':'Your account determines your portal and organisation.'}</p><form id="auth" class="form">${register||accept?field('Your name','name','','text','required maxlength="100"'):''}${field('Email','email','','email','required autocomplete="username"')}${field('Password','password','','password','required minlength="12" maxlength="128" autocomplete="'+(register||accept?'new-password':'current-password')+'"')}${register?field('Organisation name','organisation','','text','required')+select('Choose your workspace setup','template',[['general','General administration'],['workforce','People and attendance'],['equipment','Assets and equipment requests'],['documents','Documents and renewal tasks'],['expenses','Expense approval']])+ '<p class="auth-hint">Start with a ready-made setup, then choose modules and rules for your organisation during onboarding.</p>':''}<button class="primary">${register?'Create workspace':accept?'Create account':'Sign in'}</button></form><p class="error" role="alert">${esc(message)}</p><div class="auth-links"><a href="/login" class="${!owner&&!register?'current':''}">Team login</a><a href="/owner-login" class="${owner?'current':''}">Owner login</a><a href="/register" class="${register?'current':''}">Create workspace</a></div><p class="auth-hint">Your account opens the workspace and permissions assigned to you.</p></section></div>`;document.querySelector('#auth').onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target));if(accept)b.token=new URLSearchParams(location.search).get('token');try{let d=await api(register?'/auth/register':accept?'/auth/accept-invite':'/auth/login',b);me=d.user;org=me.org;message='';view=register?'onboarding':pendingExpenseId?'expenses':'dashboard';history.replaceState(null,'',d.route+(pendingExpenseId?'?expense='+encodeURIComponent(pendingExpenseId):''));await refresh()}catch(e){message=e.message;authPage()}}}
function navigation(){if(me.role==='owner')return [['dashboard','Platform dashboard'],['organisations','Organisations'],['catalogue','Module catalogue'],['platformsettings','Plans & platform settings'],...(org?[['onboarding','Workspace configuration'],['people','Users & invitations'],['connections','Data Connections'],['activity','Runtime Activity'],...(data?.workspace.modules.expenses?[['expenses','Expense Approval']]:[])]:[])];let w=data.workspace,list=[['dashboard','Dashboard']];if(me.role==='admin')list.push(['onboarding','Onboarding'],['people','Users & permissions'],['settings','Operational rules'],['connections','Data Connections']);if(w.active&&w.modules.attendance&&(me.role==='admin'||['employee','manager'].includes(me.kind)))list.push(['attendance',me.role==='admin'?'Attendance records':'My attendance'],['connected','Connected attendance']);if(w.active&&w.modules.equipment&&(me.role==='admin'||['student','approver','manager'].includes(me.kind)))list.push(['requests',me.kind==='approver'?'Assigned approvals':me.role==='admin'?'Requests & issue':'My requests']);if(me.role==='admin'&&w.modules.equipment)list.push(['inventory','Inventory'],['connected','Connected equipment']);if(w.modules.reporting)list.push(['reports',me.role==='admin'?'Organisation reports':'Personal history']);if(w.modules.notifications)list.push(['notifications','Notifications']);if(me.role==='admin')list.push(['activity','Runtime Activity'],['csv','CSV data']);if(w.modules.tasks)list.push(['tasks','Tasks & schedules']);if(w.modules.documents)list.push(['documents','Documents & records']);if(me.role==='admin')list.push(['automations','Automation templates'],['integration','Data Integration Centre']);if(w.modules.expenses)list.push(['expenses',me.kind==='employee'?'My expenses':'Expense Approval']);return list}
function render(){if(!me)return authPage();let nav=navigation();if(!nav.some(n=>n[0]===view))view='dashboard';let title=me.role==='owner'?'OperaOS Owner Portal':'Organisation / User Portal';app.innerHTML=`<aside><img class="logo" src="logo.png" alt="OperaOS"><p>${esc(title)}</p><nav>${nav.map(([id,label])=>button(label,'view',`data-view="${id}" class="${id===view?'active':''}"`)).join('')}</nav><footer>Authenticated account<br>Backend organisation permissions</footer></aside><div class="main"><header><span class="badge">${esc(title)}</span><span>${esc(me.name)} · ${esc(me.email)} · ${esc(me.role==='admin'?'Organisation Admin':me.role==='owner'?'Owner':me.kind)}</span>${button('Logout','logout')}</header><main><div class="eyebrow">${esc(data?.workspace.name||'OperaOS platform')}</div><h1>${esc(nav.find(n=>n[0]===view)[1])}</h1><div class="notice">Connected records, imported history and demonstration operations are counted separately. Email notifications and invitations are simulated.</div>${message?`<p class="feedback" role="status">${esc(message)}</p>`:''}${content()}</main></div>`;bind()}
function connectionCard(){let c=connection?.connection||{status:'Not connected'},rows=connection?.records||[];return card('Connected runtime snapshot',`<p><b>${esc(c.status)}</b> · Last successful sync: ${esc(c.lastSync||'Never')}</p>${stat([['Connected records',rows.length,'Endpoint read-back only'],['Completed hours',rows.reduce((n,r)=>n+(r.checkOut?r.hours||0:0),0).toFixed(4),'Connected attendance'],['Approved',rows.filter(r=>r.status==='approved').length,'Returned by workflow']])}<p class="data-source">Last known snapshot. Connection errors may make these records stale.</p>`)}
function content(){if(me.role==='owner'&&view==='dashboard')return stat([['Organisations',platform.organisations.length,'Separate workspaces'],['Active',platform.organisations.filter(w=>w.active).length,'Activated configurations'],['Users',platform.organisations.reduce((n,w)=>n+w.userCount,0),'Registered organisation accounts'],['Actual local records',platform.organisations.reduce((n,w)=>n+w.recordCount,0),'Backend operations']])+organisationTable();if(view==='organisations')return organisationTable();if(view==='catalogue')return card('Available module catalogue',platform.catalogue.map(m=>`<p>${esc(moduleNames[m.id]||m.id)} · ${m.enabled?'Available':'Unavailable'} ${button(m.enabled?'Disable':'Enable','catalogue',`data-id="${m.id}" data-enabled="${m.enabled?'false':'true'}"`)}</p>`).join(''));
if(view==='platformsettings')return card('Platform plans and settings',`<p>Plan labels are configurable. Billing and payment processing are unavailable.</p><form data-form="platformsettings" class="form">${field('Owner display name','ownerName',me.name)}${field('Plans (comma separated)','plans',platform.settings.plans.join(', '))}<label><input name="registrationEnabled" type="checkbox" ${platform.settings.registrationEnabled?'checked':''}>Allow organisation registration</label><button>Save platform settings</button></form>`);let w=data.workspace,rows=data.records;if(view==='expenses')return expensePage();if(['tasks','documents','automations','integration'].includes(view))return expansionContent(w);
if(view==='dashboard')return expenseSummary()+importedDashboard(w)+liveSheetCards()+connectionCard()+card('Shared module workload',workloadChart()+stat([['Open tasks',(extended.entities||[]).filter(r=>r.type==='task'&&r.status==='open').length,'Actual scoped tasks'],['Document records',(extended.entities||[]).filter(r=>r.type==='document').length,'Actual scoped documents'],['Generated reports',(extended.entities||[]).filter(r=>r.type==='report').length,'Scheduled/local reports']]))+stat([['Demonstration records',rows.length,'Scoped backend records'],['Working hours',rows.filter(r=>r.type==='attendance').reduce((n,r)=>n+r.hours,0).toFixed(4),'Calculated from completed shifts'],['Pending requests',rows.filter(r=>r.status==='pending').length,'Assigned/scoped requests'],['Imported rows',w.historical.length,'Labelled historical data']])+card('Enabled modules',Object.entries(w.modules).filter(([,enabled])=>enabled).map(([m])=>`<span class="chip">${esc(m)}</span>`).join(' '))+card('Recent activity',recordsTable(rows.slice(-8)));
if(view==='onboarding')return onboarding(w);
if(view==='settings')return rulesForm(w);
if(view==='people')return card('Individual accounts',table(['Name','Email','Role','Campus','Status','Action'],data.users.map(u=>[esc(u.name),esc(u.email),esc(u.kind),esc(u.location),u.active?'Active':'Inactive',u.id===me.id?'Your account':button(u.active?'Deactivate':'Activate','user',`data-id="${u.id}" data-active="${!u.active}"`)]))) +card('Edit account permissions',`<form data-form="permission" class="form">${select('Account','id',data.users.filter(u=>u.id!==me.id).map(u=>[u.id,u.name]))}${select('Permission','kind',['employee','manager','student','approver','admin'])}${select('Assigned location','location',w.locations)}<button>Save account permissions</button></form>`)+inviteForm(w);
if(view==='connections')return connectionForm(w);
if(view==='activity')return connectionCard()+card('Runtime execution activity',table(['Organisation','Module','Record ID','Timestamp','Action','Status','Destination','Error'],(connection.activity||[]).map(a=>[esc(a.org),esc(a.module),esc(a.recordId),esc(a.timestamp),esc(a.action),esc(a.status),esc(a.destination||'local/connected adapter'),esc(a.error)])));
if(view==='notifications')return card('Scoped notification log',data.notifications.map(n=>`<div class="activity"><b>${esc(n.text)}</b><p>${esc(n.mode)} · ${esc(n.date)}</p></div>`).join('')||'<p>No notifications.</p>');
if(view==='attendance')return (me.kind==='employee'?card('Check in / out',`<form data-form="clock" class="form">${field('Event time (local; blank uses now)','time','','datetime-local')}<label>Photo (PNG/JPEG/WebP)<input type="file" name="photo" accept="image/png,image/jpeg,image/webp" capture="user"></label>${select('Action','action',[['in','Check in'],['out','Check out']])}<button class="primary">Save attendance</button></form><p>Break deduction ${esc(w.rules.breakMinutes)} minutes; daily hours ${esc(w.rules.dailyHours)}. Photos ${w.rules.photoRequired?'required':'optional'}.</p>`):'')+card('Attendance history',recordsTable(rows.filter(r=>r.type==='attendance')))+(me.role==='admin'?card('Correct missing check-out',`<form data-form="resolve" class="form">${select('Open shift','id',rows.filter(r=>r.type==='attendance'&&!r.out).map(r=>[r.id,r.user+' · '+r.in]))}${field('Recorded check-out (local)','out','','datetime-local','required')}<button>Complete missing checkout</button></form><p>Missing end photo remains explicitly missing.</p>`):'');
if(view==='requests')return (me.kind==='student'?card('New equipment request',`<form data-form="request" class="form">${select('Campus','location',w.locations)}${select('Equipment','equipment',w.equipment.map(e=>[e.id,e.name+' · '+e.location+' · '+e.available+' available']))}${field('Quantity','qty',1,'number','min="1" required')}${field('Return due','due','','date')}<button class="primary">Submit request</button></form>`):'')+card('Requests & approvals',recordsTable(rows.filter(r=>r.type==='request')))+(me.role==='admin'?button('Run due return reminders','followups'):'');
if(view==='inventory')return card('Inventory by campus',table(['Equipment','Campus','Total','Available','Adjust'],w.equipment.map(e=>[esc(e.name),esc(e.location),e.total,e.available,`<form data-form="stock"><input name="id" type="hidden" value="${e.id}"><input name="total" type="number" value="${e.total}" min="${e.total-e.available}"><button>Adjust stock</button></form>`])))+card('Add inventory',`<form data-form="inventory" class="form">${field('Name','name','','text','required')}${select('Campus','location',w.locations)}${field('Total','total',1,'number','min="0" required')}<button>Add inventory</button></form>`);
if(view==='reports')return importedDashboard(w,true)+stat([['Visible shifts',rows.filter(r=>r.type==='attendance'&&r.out).length,'Scoped to your permission'],['Calculated hours',rows.filter(r=>r.type==='attendance').reduce((n,r)=>n+r.hours,0).toFixed(4),'Saved shift rules'],['Requests',rows.filter(r=>r.type==='request').length,'Scoped records']])+card('Records',recordsTable(rows))+card('Imported historical data',`<p>${w.historical.length} imported rows, excluded from connected totals.</p>`)+(me.role==='admin'?button('Export records CSV','export'):'');
if(view==='csv')return card('Spreadsheet-compatible CSV',`<p>Export operational records or import inventory CSV. No live Excel/Google Sheets claim is implied. Staff accounts are created through invitations.</p>${button('Export records CSV','export')}<form data-form="import" class="form"><label>Inventory CSV<input type="file" name="file" accept=".csv" required></label><p>Headers: name,location,total,available</p><button>Import inventory</button></form><form data-form="historical" class="form"><label>Historical JSON rows<input type="file" name="file" accept=".json" required></label><p>JSON array only; labelled imported history.</p><button>Import labelled history</button></form>`);
if(view==='connected')return connectedForm(w);
return ''}
function organisationTable(){return platform.organisations.map(w=>importedDashboard(w)).join('')+card('All organisation workspaces',table(['Organisation','Status','Modules','Users','Usage','Connection health','Recent automation','Manage'],platform.organisations.map(w=>[esc(w.name),w.active?'Active':'Draft/disabled',Object.entries(w.modules).filter(([,b])=>b).map(([m])=>esc(m)).join(', '),w.userCount,`${w.recordCount} local / ${w.connectedCount} connected`,esc(w.connection?.status||'Not connected')+(w.modules.expenses?'<br>Expense Excel: '+esc(w.expenseConnection?.excel?.status||'Not connected')+'<br>Teams: '+esc(w.expenseConnection?.teams?.status||'Not connected'):''),esc(w.activity[0]?.action||'None'),button('Configure','selectorg',`data-id="${w.id}"`)+button(w.active?'Disable':'Enable','orgtoggle',`data-id="${w.id}" data-active="${!w.active}"`)])))}
function rulesForm(w){return card('Operational rules',`<form data-form="rules" class="form">${field('Plan label','plan',w.plan||'Starter')}${field('Daily regular hours','dailyHours',w.rules.dailyHours,'number','step="0.5" min="0.5" max="24" required')}${field('Break minutes','breakMinutes',w.rules.breakMinutes,'number','min="0" max="480" required')}${field('Default return days','returnDays',w.rules.returnDays,'number','min="1" max="365" required')}<label><input type="checkbox" name="photoRequired" ${w.rules.photoRequired?'checked':''}>Require attendance photos</label>${field('Collection instructions','collection',w.rules.collection)}${field('Return instructions','returns',w.rules.returns)}${me.role==='admin'?'<label><input name="ownerRecordAccess" type="checkbox" '+(w.ownerRecordAccess?'checked':'')+'>Grant and log platform owner access to organisation records</label>':''}<button>Save rules</button></form>`)}
function inviteForm(w){return card('Invite an individual user',`<form data-form="invite" class="form">${field('Email','email','','email','required')}${select('Permission','kind',['employee','manager','student','approver','admin'])}${select('Location / campus','location',w.locations)}<button>Create invitation</button></form><p>One-use invitation expires in 24 hours. Copy its link to the intended test recipient; outgoing email is simulated.</p><p id="invite-url"></p>`)}
function onboarding(w){let names=['Organisation details','Select modules','Connect/import data','Map fields','Configure rules','Invite users','Test','Activate'],step=w.stage;let body=`<div class="steps">${names.map((n,i)=>button(`${i+1}. ${n}`,'stage',`data-stage="${i+1}" class="${step===i+1?'current':''}"`)).join('')}</div>`;if(step===1)body+=card('Organisation details',`<form data-form="details" class="form">${field('Organisation name','name',w.name,'text','required')}${field('Locations (comma separated)','locations',w.locations.join(', '),'text','required')}<button>Save details</button></form>`);if(step===2)body+=card('Modules',`<form data-form="modules" class="form">${data.catalogue.map(m=>`<label><input name="${m.id}" type="checkbox" ${w.modules[m.id]?'checked':''} ${!m.enabled?'disabled':''}>${esc(moduleNames[m.id]||m.id)} ${!m.enabled?'(unavailable)':''}</label>`).join('')}<button>Save modules</button></form>`);if(step===3)body+=(w.type==='expenses'?'':connectionForm(w))+integrationCentre(w)+(w.modules.expenses?expensePage(true):'');if(step===4)body+=integrationCentre(w)+(w.modules.expenses?expensePage(true):'');if(step===5)body+=rulesForm(w)+(w.modules.expenses?expensePage(true):'');if(step===6)body+=inviteForm(w);if(step===7||step===8)body+=card('Test and activate',`${button('Run configuration test','testorg')} ${button('Activate workspace','activate')}<p>Configuration testing is separate from live endpoint verification. Disconnected workflows remain Not connected.</p>${table(['Time','Passed','Errors'],w.tests.map(t=>[esc(t.date),String(t.passed),esc(t.errors.join(' '))]))}`);return body+(step<8?button('Save progress / next step','stage',`data-stage="${step+1}"`):'')}
function connectionForm(w){let c=connection?.connection||{};return connectionCard()+card('Per-organisation connection',`<p>Endpoint credentials come only from backend environment variables. Mapping and configuration are saved per workspace.</p><form data-form="connection" class="form">${field('Connection label','label',c.label||'Dedicated test resource')}${w.type==='attendance'?field('Test Google spreadsheet URL','sheetURL',c.sheetId?'https://docs.google.com/spreadsheets/d/'+c.sheetId+'/edit':'','url','required')+['id','organisation','employeeId','employeeName','checkIn','checkOut','hours','demo','breakMinutes','dailyHours','status'].map(k=>field('Column: '+k,k,c.mapping?.[k]||k)).join(''):''}<label><input name="testResource" type="checkbox" required>Separate test resource confirmed</label><button>Save connection mapping</button></form>${button('Test real connection','testconnection')} ${button('Sync endpoint records','sync')}<p>New workspace endpoints are supplied by an administrator in the backend environment; credentials are never editable by employees.</p>`)}
function connectedForm(w){return connectionCard()+card('Connected demonstration transaction',w.type==='attendance'?`<form data-form="connected-attendance" class="form">${me.role==='admin'?field('Demo employee ID','employeeId','DEMO-TEST')+field('Demo employee name','employeeName','Fictional employee'):''}${field('Event time (local; blank uses now)','time','','datetime-local')}${select('Action','action',[['in','Check in'],['out','Check out']])}<button>Write and read back from test sheet</button></form>`:`<form data-form="connected-request" class="form">${select('Campus','campus',w.locations)}${field('Equipment','equipment','Demonstration laptop')}${field('Quantity','quantity',1,'number','min="1" max="100"')}<button>Send to test workflow</button></form>`)+card('Endpoint records',table(['Record ID','Account / campus','Status','Hours','Action'],(connection.records||[]).map(r=>[esc(r.id),esc(r.employeeId||r.campus),esc(r.status||'saved'),esc(r.hours??'—'),w.type==='equipment'&&me.role==='admin'?button('Fetch approval status','remoteapproval',`data-id="${r.id}"`):'—'])))}
function recordsTable(rows){return table(['Record ID / source','Account','Record','Result','Action'],rows.map(r=>{let actions='';if(r.type==='request'){if(me.kind==='approver'&&r.status==='pending')actions=button('Approve','requestaction',`data-id="${r.id}" data-op="approve"`)+button('Reject','requestaction',`data-id="${r.id}" data-op="reject"`);if(me.role==='admin'&&r.status==='approved')actions=button('Issue','requestaction',`data-id="${r.id}" data-op="issue"`);if(me.role==='admin'&&r.status==='issued')actions=button('Confirm return','requestaction',`data-id="${r.id}" data-op="return"`)}return [esc(r.id)+`<br><small>${esc(r.source)}</small>`,esc(data.users.find(u=>u.id===r.user)?.name||r.user),r.type==='attendance'?esc(r.in)+' → '+esc(r.out||'Open'):esc(r.location)+' · '+esc(data.workspace.equipment.find(e=>e.id===r.equipment)?.name||r.equipment),r.type==='attendance'?Number(r.hours).toFixed(4)+' hours'+`<details><summary>Photo evidence</summary>${r.inPhoto?'<img width="130" src="'+esc(r.inPhoto)+'" alt="Check-in photo">':'Check-in photo missing'} ${r.outPhoto?'<img width="130" src="'+esc(r.outPhoto)+'" alt="Check-out photo">':'Check-out photo missing'}${r.correction?'<p>'+esc(r.correction)+'</p>':''}</details>`:esc(r.status)+(r.status==='issued'&&r.due<new Date().toISOString().slice(0,10)?' · overdue':''),actions||'—']}))}
function csvRows(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Unclosed CSV quote');row.push(cell);if(row.some(Boolean))rows.push(row);let headers=rows.shift();return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h.trim(),r[i]?.trim()]))) }
function photo(file){return new Promise((resolve,reject)=>{if(!file||!file.size)return resolve('');if(file.size>550000)return reject(Error('Choose a photo under 550 KB.'));let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function bind(){let search=document.querySelector('#entity-search');if(search)search.oninput=()=>{document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(search.value.toLowerCase()))};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{try{let a=b.dataset.action;message='';if(await expansionAction(a,b))return;if(a==='view'){view=b.dataset.view;render();return}if(a==='logout'){await api('/auth/logout',{});me=null;data=null;connection=null;org='';pendingExpenseId='';expenseData=null;history.replaceState(null,'','/login');authPage();return}if(a==='selectorg'){org=b.dataset.id;view='onboarding'}if(a==='orgtoggle')await api('/api/platform/organisation',{id:b.dataset.id,active:b.dataset.active==='true'});if(a==='catalogue')await api('/api/platform/catalogue',{id:b.dataset.id,enabled:b.dataset.enabled==='true'});if(a==='stage')await api('/api/'+org+'/onboarding',{stage:Number(b.dataset.stage)});if(a==='testorg'){let result=await api('/api/'+org+'/onboarding',{action:'test'});message=result.passed?'Configuration test passed.':result.errors.join(' ')}if(a==='activate')await api('/api/'+org+'/onboarding',{action:'activate'});if(a==='user')await api('/api/'+org+'/users',{id:b.dataset.id,active:b.dataset.active==='true'});if(a==='requestaction')await api('/api/'+org+'/local',{type:'request',action:b.dataset.op,id:b.dataset.id});if(a==='followups'){let d=await api('/api/'+org+'/local',{type:'request',action:'followups'});message=d.count+' simulated reminder(s) logged.'}if(a==='testconnection')await api('/api/'+org+'/test',{});if(a==='sync')await api('/api/'+org+'/sync',{});if(a==='remoteapproval')await api('/api/'+org+'/approval',{id:b.dataset.id});if(a==='export'){let d=await api('/api/'+org+'/export'),keys=['id','type','user','in','out','hours','location','qty','status','source'];let cell=x=>'"'+String(x??'').replace(/^[\s]*([=+@-])/,'\'$1').replace(/"/g,'""')+'"';let text=[keys,...d.records.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\r\n');let url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv'})),link=document.createElement('a');link.href=url;link.download='operaos-records.csv';link.click();URL.revokeObjectURL(url)}await refresh()}catch(e){message=e.message;render()}});
 document.querySelectorAll('[data-form]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(form)),t=form.dataset.form;try{message='';if(t==='permission')await api('/api/'+org+'/users',f);if(t==='stock')await api('/api/'+org+'/local',{type:'request',action:'stock',...f});if(t==='resolve')await api('/api/'+org+'/local',{type:'attendance',action:'resolve',id:f.id,out:new Date(f.out).toISOString()});if(await expansionForm(t,f,form))return;if(t==='details')await api('/api/'+org+'/settings',{name:f.name,locations:f.locations.split(',').map(s=>s.trim()).filter(Boolean)});if(t==='rules')await api('/api/'+org+'/settings',{plan:f.plan,ownerRecordAccess:me.role==='admin'?f.ownerRecordAccess==='on':undefined,rules:{dailyHours:Number(f.dailyHours),breakMinutes:Number(f.breakMinutes),returnDays:Number(f.returnDays),photoRequired:f.photoRequired==='on',collection:f.collection,returns:f.returns}});if(t==='modules')await api('/api/'+org+'/settings',{modules:Object.fromEntries(data.catalogue.map(m=>[m.id,f[m.id]==='on']))});if(t==='invite'){let d=await api('/api/'+org+'/invite',f);await refresh();document.querySelector('#invite-url').textContent=location.origin+d.url;return}if(t==='connection')await api('/api/'+org+'/configure',{label:f.label,sheetURL:f.sheetURL,testResource:f.testResource==='on',mapping:Object.fromEntries(['id','organisation','employeeId','employeeName','checkIn','checkOut','hours','demo','breakMinutes','dailyHours','status'].map(k=>[k,f[k]]))});if(t==='clock')await api('/api/'+org+'/local',{type:'attendance',action:f.action,time:f.time?new Date(f.time).toISOString():'',photo:await photo(f.photo)});if(t==='request')await api('/api/'+org+'/local',{...f,type:'request',action:'request'});if(t==='inventory')await api('/api/'+org+'/import',{type:'equipment',rows:[{...f,total:Number(f.total),available:Number(f.total)}]});if(t==='import')await api('/api/'+org+'/import',{type:'equipment',rows:csvRows(await f.file.text())});if(t==='historical')await api('/api/'+org+'/import',{type:'historical',rows:JSON.parse(await f.file.text())});if(t==='connected-attendance')await api('/api/'+org+'/attendance',{...f,time:f.time?new Date(f.time).toISOString():''});if(t==='connected-request')await api('/api/'+org+'/request',f);await refresh()}catch(e){message=e.message;render()}})}
async function start(){try{let d=await api('/auth/me');me=d.user;org=me.org;let expected=d.route;if(pendingExpenseId)view='expenses';if(!location.pathname.startsWith(expected))history.replaceState(null,'',expected+(pendingExpenseId?'?expense='+encodeURIComponent(pendingExpenseId):''));await refresh()}catch{me=null;authPage()}}
start();
const moduleNames={expenses:'Expense Approval',attendance:'Workforce Operations',approvals:'Request & Workflow Management',equipment:'Asset & Inventory Control',tasks:'Task & Schedule Automation',documents:'Document & Records Management',notifications:'Communications Automation',reporting:'Reporting & Operational Analytics'};
function expansionContent(w){let entities=extended?.entities||[];if(view==='integration')return integrationCentre(w);if(view==='automations')return card('Shared triggers, conditions and actions',`<p>Rules run every 30 seconds while the backend is running. Action keys prevent duplicate execution. Notifications are simulated; connected writes require a verified provider.</p><form data-form="automation" class="form">${select('Template','template',['document-expiry','low-stock','overdue-task','approved-request','scheduled-report','recurring-task'])}${field('Recurring task title','title','Recurring operational task')}${field('Expiry window (days)','days',7,'number','min="0" max="365"')}${field('Low-stock threshold','threshold',0,'number','min="0"')}${field('Target stock','target',5,'number','min="1"')}${field('Report interval (minutes)','intervalMinutes',1440,'number','min="1"')}<button>Save automation rule</button></form>${button('Run shared automation now','runautomation')}${table(['Template','Enabled','Action'],(extended.rules||[]).map(r=>[esc(r.template),String(r.enabled),button(r.enabled?'Disable':'Enable','togglerule',`data-id="${r.id}"`)]))}`);
let type=view==='tasks'?'task':'document',rows=entities.filter(r=>r.type===type);return card(type==='task'?'Tasks, deadlines and escalation':'Documents, ownership and expiry',`<form data-form="entity" class="form"><input type="hidden" name="type" value="${type}">${field('Title','title','','text','required')}${type==='task'?field('Deadline','due','','datetime-local'):field('Expiry date','expiry','','date')+field('Category','category','General')+'<label>Optional upload (PDF, text, PNG/JPEG; max 1 MB)<input type="file" name="file" accept="application/pdf,text/plain,image/png,image/jpeg"></label>'}<button>Create record</button></form><label>Search records<input id="entity-search" type="search" placeholder="Title, category or status"></label>${table(['Title / ID','Due / expiry','Status / source','Actions'],rows.map(r=>[esc(r.title)+'<br><small>'+esc(r.id)+'</small>',esc(r.due||r.expiry||'—'),esc(r.status||r.category||'')+' · '+esc(r.source),type==='task'?button('Complete','completetask',`data-id="${r.id}"`):r.fileName?button('Download','downloaddoc',`data-id="${r.id}"`):'Metadata only']))}`)}
function integrationCentre(w){return card('Data Integration Centre',`<p>File imports are snapshots. Ongoing sources are separate connections. Tokens stay in backend environment variables. Sources are assigned to individual modules.</p>${table(['Capability','Availability'],Object.entries(extended?.capabilities||{}).map(([k,v])=>[esc(k),esc(v)]))}<form data-form="preview" class="form"><label>Excel (.xlsx) or CSV file<input name="file" type="file" accept=".xlsx,.csv" required></label>${field('Sheet/tab name (blank selects first)','tab')}${select('Source label','source',[['demonstration','Demonstration import'],['historical','Historical import']])}<button>Preview file</button></form>${preview?`<p>${esc(preview.fileName)} · ${preview.total} rows · tab ${esc(preview.tab)}. Available tabs: ${esc(preview.tabs.join(', '))}</p>${table(preview.headers,preview.rows.map(r=>r.map(esc)))}<form data-form="commit-import" class="form">${select('Import into module','type',[['document','Document records'],['task','Tasks']])}${select('Map title','title',preview.headers)}${select('Map expiry','expiry',['',...preview.headers])}${select('Map deadline','due',['',...preview.headers])}${select('Map category','category',['',...preview.headers])}<button>Validate and import without duplicates</button></form>`:''}${button('Export Excel workbook','exportxlsx')} ${button('Export combined CSV','exportcombinedcsv')}<h3>Ongoing source configuration</h3><form data-form="source" class="form">${select('Module','module',Object.entries(w.modules).filter(([,on])=>on).map(([m])=>[m,moduleNames[m]||m]))}${select('Connector','type',['googleSheets','googleDrive','connectedExcel'])}${field('Google spreadsheet ID','spreadsheetId')}${field('Sheet/tab','tab')}${field('Source label','label')}${field('Header row number','headerRow','1','number')}${field('Map record ID header','recordId')}${field('Map employee / driver ID header','employeeId')}${field('Map recorded hours header','hours')}${field('Map stock quantity header','quantity')}${field('Map approval status header','status')}${field('Google Drive folder ID','folderId')}${field('Microsoft Drive ID','driveId')}${field('Excel workbook item ID','itemId')}${field('Excel table name','table')}<label><input name="write" type="checkbox">Allow writes</label><button>Save data source</button></form>${table(['Module / source ID','Connector','Permissions','Status','Last sync','Actions'],(extended?.sources||[]).map(s=>[esc(moduleNames[s.module]||s.module)+'<br>'+esc(s.id),esc(s.type),'Read'+(s.write?' / write':''),esc(s.status),esc(s.lastSync||'Never'),button('Test','sourcetest',`data-id="${s.id}"`)+button(s.type==='googleDrive'?'Select Drive files':'Preview records','sourceread',`data-id="${s.id}"`)+(s.type==='googleDrive'&&s.write?button('Save report to Drive','driveupload',`data-id="${s.id}"`):'')]))}<form data-form="source-write" class="form">${select('Writable source','sourceId',(extended?.sources||[]).filter(s=>s.write&&s.type!=='googleDrive').map(s=>[s.id,s.type+' / '+s.module]))}<label>Rows to append (JSON array of row arrays)<textarea name="values" required placeholder='[["DEMO-RECORD","fictional value"]]'></textarea></label><button>Append bounded test rows</button></form><p id="provider-result"></p><p>Generic record writes are available through the authenticated source-write API with bounded values. Automatic OAuth token refresh, full shift planning and a visual arbitrary-rule builder are unavailable. Provider credentials and permissions require external setup.</p>`)}
async function platformAPI(body){return api('/api/'+org+'/platform',body)}
async function expansionForm(t,f,form){if(t.startsWith('expense-'))return expenseForm(t,f,form);if(t==='source-write'){let d=await platformAPI({action:'source-write',sourceId:f.sourceId,values:JSON.parse(f.values)});await refresh();message='Provider write confirmed; inspect source records for verification.';render();return true}if(t==='platformsettings'){let profile=await api('/auth/profile',{name:f.ownerName});me=profile.user;await api('/api/platform/settings',{plans:f.plans.split(',').map(x=>x.trim()),registrationEnabled:f.registrationEnabled==='on'});message='Platform settings saved.';await refresh();return true}if(t==='entity'){let body={...f,action:f.type};if(f.file?.size){let bytes=await file64(f.file);body.content=bytes;body.fileName=f.file.name;body.mime=f.file.type}if(body.expiry)body.expiry=new Date(body.expiry).toISOString();if(body.due)body.due=new Date(body.due).toISOString();await platformAPI(body);await refresh();return true}if(t==='automation'){await platformAPI({...f,action:'rule'});await refresh();return true}if(t==='source'){await platformAPI({...f,action:'source',mapping:{recordId:f.recordId,employeeId:f.employeeId,hours:f.hours,quantity:f.quantity,status:f.status},write:f.write==='on'});await refresh();return true}if(t==='preview'){preview=await platformAPI({action:'preview',fileName:f.file.name,content:await file64(f.file),tab:f.tab,source:f.source});render();return true}if(t==='commit-import'){let result=await platformAPI({action:t,previewId:preview.id,type:f.type,mapping:{title:f.title,expiry:f.expiry,due:f.due,category:f.category}});preview=null;message=result.created+' records imported; '+result.duplicates+' duplicates prevented.';await refresh();return true}return false}
async function expansionAction(a,b){if(a==='refreshsheet'){await platformAPI({action:'source-read',sourceId:b.dataset.id});await refresh();return true}if(a.startsWith('expense-'))return expenseAction(a,b);if(['exportxlsx','exportcombinedcsv'].includes(a)){let d=await platformAPI({action:'export-file',format:a==='exportxlsx'?'xlsx':'csv'});let url=URL.createObjectURL(new Blob([Uint8Array.from(atob(d.content),c=>c.charCodeAt(0))],{type:d.mime})),link=document.createElement('a');link.href=url;link.download=d.fileName;link.click();URL.revokeObjectURL(url);return true}if(a==='runautomation'){let result=await platformAPI({action:'run'});message=result.executed+' automation action(s) executed.';await refresh();return true}if(a==='togglerule'){let rule=extended.rules.find(r=>r.id===b.dataset.id);await platformAPI({...rule,action:'rule',enabled:!rule.enabled});await refresh();return true}if(a==='completetask'){let r=extended.entities.find(r=>r.id===b.dataset.id);await platformAPI({...r,action:'task',status:'completed'});await refresh();return true}if(a==='downloaddoc'){let d=await platformAPI({action:'download',id:b.dataset.id}),bytes=Uint8Array.from(atob(d.content),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:d.mime})),link=document.createElement('a');link.href=url;link.download=d.fileName;link.click();URL.revokeObjectURL(url);return true}if(a==='selectdrivefile'){await platformAPI({action:'select-file',sourceId:b.dataset.id,fileId:b.dataset.file});message='Drive file selection verified and saved.';await refresh();return true}if(['sourcetest','sourceread','driveupload'].includes(a)){let s=extended.sources.find(s=>s.id===b.dataset.id),action=a==='driveupload'?'drive-upload':s.type==='googleDrive'?'drive-list':a==='sourcetest'?'source-test':'source-read';let d=await platformAPI({action,sourceId:s.id});await refresh();let result=document.querySelector('#provider-result');if(s.type==='googleDrive'&&Array.isArray(d.result.files)){result.innerHTML=d.result.files.map(f=>'<span>'+esc(f.name)+' '+button('Select file','selectdrivefile','data-id="'+s.id+'" data-file="'+esc(f.id)+'"')+'</span><br>').join('');bind()}else result.textContent=JSON.stringify(d.result);return true}return false}
function file64(file){return new Promise((resolve,reject)=>{if(file.size>3000000)return reject(Error('Choose a file under 3 MB.'));let r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)})}

function workloadChart(){let rows=[...(data?.records||[]),...(extended?.entities||[])],counts=['attendance','request','document','task','report'].map(t=>[t,rows.filter(r=>r.type===t).length]),max=Math.max(1,...counts.map(([,n])=>n));return '<figure class="workload-chart" aria-label="Record counts by module">'+counts.map(([t,n])=>'<div class="chart-row"><span>'+esc(t)+'</span><div class="chart-track"><div class="chart-bar" style="width:'+n/max*100+'%"></div></div><strong>'+n+'</strong></div>').join('')+'</figure>'}
setInterval(()=>{if(me&&document.visibilityState==='visible'&&['dashboard','notifications','activity'].includes(view))refresh().catch(e=>{message=e.message;render()})},30000);

function importedDashboard(w,details=false){let result='';let groups=w.attendanceSummary||[];if(groups.length){let entries=groups.reduce((n,g)=>n+g.entries,0),hours=groups.reduce((n,g)=>n+g.hours,0),shifts=groups.reduce((n,g)=>n+g.shifts,0),dates=[...new Set(groups.flatMap(g=>g.dates))].sort();result+=card('MTG imported attendance',`<p>Imported historical Excel data · ${esc(dates[0])} to ${esc(dates.at(-1))} · imported ${esc(w.importedAt||'locally')}. This is a saved file snapshot, not live data.</p>${stat([['Attendance entries',entries,'Valid employee ID and date'],['Completed shifts',shifts,'Recorded hours greater than zero'],['Recorded hours',hours.toFixed(2),'Source workbook values'],['Days with records',dates.length,'Distinct imported dates']])}${table(['Workforce','Employees with records','Entries','Completed shifts','Hours','Overtime'],groups.map(g=>[esc(g.group),g.employees,g.entries,g.shifts,g.hours.toFixed(2),g.group==='Drivers'?g.overtime.toFixed(2):'Not supplied']))}<p>${Number(w.importWarnings||0)} rows skipped for invalid dates. Export date corrections are recorded per row.</p>${details?table(['Date','Workforce','Employee','Hours','Source row'],(w.historical||[]).slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,100).map(r=>[esc(r.date),esc(r.group),esc(r.employeeName||r.employeeId),r.hours===null?'Not recorded':esc(r.hours),esc(r.fileName)+' / '+r.sourceRow])):''}`)}let demo=w.demoRequests||[];if(demo.length){let counts={};for(let r of demo)counts[r.status]=(counts[r.status]||0)+1;result+=card('QAHE request demonstration',`<p><b>Demo — fictional data.</b> ${demo.length} fictional requests illustrate your stated baseline of “390 official form submissions”. The actual forms have not been imported; campus and status allocations below are invented.</p>${stat([['Fictional requests',demo.length,'Demonstration records'],['Pending',counts.pending||0,'Fictional status'],['Approved',counts.approved||0,'Fictional status'],['Issued',counts.issued||0,'Fictional status']])}${table(['Campus','Fictional requests'],['Manchester','London','Birmingham'].map(c=>[c,demo.filter(r=>r.location===c).length]))}${table(['Status','Fictional count'],Object.entries(counts).map(([k,n])=>[esc(k),n]))}${details?table(['Request ID','Fictional student','Campus','Equipment','Status'],demo.slice(0,30).map(r=>[r.id,esc(r.student),r.location,esc(r.equipment),r.status])):''}<p>Illustration only. Submit new requests through Requests & issue to exercise the operational workflow.</p>`)}return result}

const expenseFields=['requestId','employeeId','employeeName','amount','currency','category','description','managerId','status','submittedAt','decidedAt','decidedBy','comment','dataMode'];
const expenseAPI=(action,body={})=>api('/api/'+org+'/expenses/'+action,body);
function expenseSummary(){if(!expenseData)return '';let rows=expenseData.records;return card('Expense Approval · v1.0.0',stat([['Visible expenses',rows.length,'Permitted organisation records'],['Pending',rows.filter(r=>r.status==='pending').length,'Awaiting assigned manager'],['Approved',rows.filter(r=>r.status==='approved').length,'Recorded decisions'],['Approved amount',rows.filter(r=>r.status==='approved'&&r.currency===expenseData.settings.currency).reduce((n,r)=>n+r.amount,0).toFixed(2),expenseData.settings.currency+' only']]))}
function expensePage(configOnly=false){if(!expenseData)return card('Expense Approval','<p>Enable this module to begin.</p>');let d=expenseData,c=d.settings,choices=[['','Choose manager'],...d.managers.map(m=>[m.id,m.name+' · '+m.kind])];let html=card('Expense Approval · '+esc(c.version),`<p><b>${esc(c.dataMode)} data</b> · Built-in form and manager decisions. External integrations have separate status.</p>`);if(!configOnly)html+=expenseSummary();if(d.canConfigure){html+=card('Saved approval rules',`<p>Category routing takes precedence. Otherwise amounts above the threshold route to the high-value manager; all others use the default manager. Saving rules requires a new configuration test.</p><form data-form="expense-settings" class="form">${field('Categories (comma separated)','categories',c.categories.join(', '))}${field('Currency (three-letter code)','currency',c.currency)}${select('Default authorised manager','managerId',choices,c.managerId)}${field('High-value threshold','threshold',c.threshold,'number','min="0" step="0.01"')}${select('High-value manager (optional)','highManagerId',choices,c.highManagerId)}${select('Record mode','dataMode',['Demo','Production'],c.dataMode)}${c.categories.map(category=>select('Route '+category+' (optional)','route:'+category,choices,c.categoryRoutes?.[category]||'')).join('')}<label><input type="checkbox" name="notifications" ${c.notifications?'checked':''}>Notify assigned manager</label>${field('Excel Drive ID','driveId',c.excel.driveId)}${field('Excel workbook item ID','itemId',c.excel.itemId)}${field('Excel table name','table',c.excel.table)}${expenseFields.map(f=>field('Excel column: '+f,'map:'+f,c.excel.mapping[f]||f)).join('')}${d.managers.map(m=>field('Teams chat ID for '+m.name,'chat:'+m.id,c.teams.chats?.[m.id]||'')).join('')}<button>Save expense configuration</button></form><div class="toolbar">${button('Test rules','expense-test')}${button('Activate Expense workspace','expense-activate')}${button('Browse Microsoft workbook destinations','expense-destinations')}${button('Test Excel connection','expense-exceltest')}${button('Test Teams connection','expense-teamstest')}</div><p>Rules: ${c.tested?'Passed configuration test':'Test required'}. Excel: ${esc(c.excel.status)}. Teams: ${esc(c.teams.status)}.</p>${c.excel.error?'<p class="error">'+esc(c.excel.error)+'</p>':''}${c.teams.error?'<p class="error">'+esc(c.teams.error)+'</p>':''}${c.excel.columns?'<p>Verified Excel columns: '+c.excel.columns.map(esc).join(', ')+'</p>':''}<p>Keep tokens in backend environment variables. Uploading an Excel file is a historical snapshot and does not create a live connection.</p>${expenseDestinations?table(['Workbook / folder','Item ID'],(expenseDestinations.files||[]).map(f=>[esc(f.name),esc(f.id)+(f.file?button('Select workbook','expense-selectworkbook','data-id="'+esc(f.id)+'"'):'')]))+'<p>Drive ID: '+esc(expenseDestinations.driveId)+'</p>':''}`)}
if(configOnly)return html;if(d.canSubmit)html+=card('Submit an expense',`<form data-form="expense-submit" class="form"><input name="idempotencyKey" type="hidden" value="${crypto.randomUUID()}">${field('Amount ('+c.currency+')','amount','','number','required min="0.01" max="1000000" step="0.01"')}${select('Category','category',c.categories)}<label>Description<textarea name="description" required minlength="3" maxlength="2000"></textarea></label><label>Receipt · PDF, PNG or JPEG · up to 1 MB<input name="receipt" type="file" accept=".pdf,.png,.jpg,.jpeg" required></label><button>Submit for approval</button></form>`);let selected=new URLSearchParams(location.search).get('expense');let rows=selected?d.records.filter(r=>r.id===selected):d.records;html+=card(d.canDecide?'Assigned approval queue and decisions':'Expense history',selected?'<p>Request link opens a permitted record. Opening it never approves the expense.</p>':'');html+=card('Requests',table(['Request / source','Employee / category','Amount','Decision / manager','External steps','Actions'],rows.map(r=>[esc(r.id)+'<br>'+esc(r.dataMode)+' · '+esc(r.submittedAt),esc(r.employeeName)+'<br>'+esc(r.category)+'<br>'+esc(r.description),esc(r.amount.toFixed(2))+' '+esc(r.currency),esc(r.status)+'<br>Manager: '+esc(d.managers.find(m=>m.id===r.managerId)?.name||r.managerId)+(r.decidedAt?'<br>'+esc(r.decidedAt)+'<br>By: '+esc(r.decidedBy)+'<br>'+esc(r.comment):''),(r.jobs||[]).map(j=>esc(j.destination)+' · '+esc(j.status)+(j.error?'<br>'+esc(j.error):'')).join('<br>'),button('Receipt','expense-receipt','data-id="'+r.id+'"')+((d.canConfigure||r.managerId===me.id)?button('Retry external steps','expense-retry','data-id="'+r.id+'"'):'')+(d.canDecide&&r.managerId===me.id&&r.status==='pending'?`<form data-form="expense-decision" class="form"><input type="hidden" name="id" value="${r.id}">${select('Decision','decision',['approved','rejected'])}<label>Decision comment<textarea name="comment" required maxlength="1000"></textarea></label><button>Save decision</button></form>`:'')])));if(d.logs?.length)html+=card('Expense execution logs',table(['Organisation','Request ID','Timestamp','Action','Result','Destination','Error'],d.logs.map(l=>[esc(l.org),esc(l.recordId),esc(l.timestamp),esc(l.action),esc(l.status),esc(l.destination),esc(l.error)])));return html}
async function expenseForm(t,f,form){let action=t.slice(8),b={...f};form.querySelector('button').disabled=true;try{if(action==='settings'){let c=expenseData.settings;b={...c,categories:f.categories.split(',').map(x=>x.trim()).filter(Boolean),currency:f.currency.toUpperCase(),managerId:f.managerId,highManagerId:f.highManagerId,threshold:Number(f.threshold),dataMode:f.dataMode,notifications:f.notifications==='on',categoryRoutes:Object.fromEntries(Object.entries(f).filter(([k,v])=>k.startsWith('route:')&&v).map(([k,v])=>[k.slice(6),v])),excel:{...c.excel,driveId:f.driveId,itemId:f.itemId,table:f.table,mapping:Object.fromEntries(expenseFields.map(k=>[k,f['map:'+k]]))},teams:{...c.teams,chats:Object.fromEntries(Object.entries(f).filter(([k,v])=>k.startsWith('chat:')&&v).map(([k,v])=>[k.slice(5),v]))}}}if(action==='submit'){if(f.receipt.size>1e6)throw Error('Choose a receipt under 1 MB.');b.receipt={name:f.receipt.name,mime:f.receipt.type,content:await file64(f.receipt)}}let result=await expenseAPI(action,b);message=action==='submit'?'Expense saved and routed. External step status is shown separately.':'Saved successfully.';await refresh();return true}finally{form.querySelector('button')?.removeAttribute('disabled')}}
async function expenseAction(a,b){let action=a.slice(8),body={id:b.dataset.id};if(['exceltest','teamstest'].includes(action)){body.destination=action==='exceltest'?'excel':'teams';action='connection-test'}if(action==='receipt'){let d=await expenseAPI(action,body),url=URL.createObjectURL(new Blob([Uint8Array.from(atob(d.content),c=>c.charCodeAt(0))],{type:d.mime})),link=document.createElement('a');link.href=url;link.download=d.name||'receipt';link.click();URL.revokeObjectURL(url);return true}if(action==='selectworkbook'){let result=await expenseAPI('destinations',{driveId:expenseDestinations.driveId,itemId:b.dataset.id});let form=document.querySelector('[data-form=expense-settings]');form.elements.driveId.value=expenseDestinations.driveId;form.elements.itemId.value=b.dataset.id;form.elements.table.value=result.tables?.[0]?.name||'';message='Workbook selected. Tables: '+(result.tables||[]).map(t=>t.name).join(', ')+'. Review the table and save configuration.';let note=document.createElement('p');note.textContent=message;form.before(note);return true}let result=await expenseAPI(action,body);if(action==='destinations')expenseDestinations=result;message=action==='test'?result.passed?'Expense rules passed testing.':result.errors.join(' '):'Action completed. Check recorded connection and execution status.';await refresh();return true}

function liveSheetCards(){return (extended?.sources||[]).filter(s=>s.type==='googleSheets').map(s=>card(esc(s.label||s.tab),`<p>Operational sheet · ${esc(s.status)} · ${s.write?'Writes enabled':'Read only'}</p><p>Last successful read: ${esc(s.snapshot?.readAt||'Never')}. Counts below describe that snapshot; refresh to retrieve changes.</p>${s.error?'<p class="error">'+esc(s.error)+'</p>':''}${s.snapshot?stat([['Sheet records',s.snapshot.stats.records,'Mapped, nonempty rows'],['Employees',s.snapshot.stats.employees,'Distinct mapped IDs'],['Recorded hours',s.snapshot.stats.hours,'Source sheet values'],['Stock quantity',s.snapshot.stats.quantity,'Mapped source quantities']])+table(['Status','Count'],Object.entries(s.snapshot.stats.statuses).map(([k,v])=>[esc(k),v])):'<p>No connected records read yet.</p>'}${me.role==='admin'?button('Refresh sheet statistics','refreshsheet','data-id="'+s.id+'"'):''}`)).join('')}
